                "[\"Uno de los 4 o 5 piperos del país. Pieza en el Museo de la Pipa de Ámsterdam y en el Museo del Tabaco de Salta. Miembro de la Asociación de Piperos Interamericana y del Hobbit Pipe Club.\",\"Ya exporta a Francia, Estados Unidos e Italia, y genera turismo de cofradía espontáneo: le llegan clientes desde Santa Cruz, Tierra del Fuego y Neuquén.\",\"Taller, maquinaria e insumos propios. Viabilidad operativa inmediata, sin inversión previa.\",\"Producto con Sello Origen Chubut.\",\"El cuello no es el producto: es difusión y comercialización. No tiene tiempo ni recursos propios y depende de su hijo para el video.\",\"No busca masificar la venta. Quiere movimiento dentro de un nicho definido.\"]",
                "[\"Camino de acceso al taller detonado. Condiciona cualquier visita organizada.\",\"No disponible lunes ni miércoles por la mañana.\",\"Costo y logística de envío internacional, hoy artesanal.\"]",
                "[{\"t\":\"Monetizar la visita al taller\",\"items\":[\"Cuantificar el tiempo de producción que cede en cada visita.\",\"Guion segmentado: cofrades y coleccionistas por un lado, turistas y familias por otro.\",\"Precio por visita más esquema de escasez: de 3 a 5 días por pieza significa agenda acotada.\"]},{\"t\":\"Contenido y comunicación\",\"items\":[\"Producción audiovisual 4K y dron con equipo de la Subsecretaría, vinculando la pipa al entorno patagónico.\",\"Curaduría del canal de YouTube existente y de las redes.\"]},{\"t\":\"Vinculación institucional y comercial\",\"items\":[\"Presencia con respaldo de Turismo en encuentros locales (Carao, Hotel Welches, Cifarm), no solo stand.\",\"Circuito de regalo institucional y empresarial.\",\"Gestión del camino de acceso ante el área que corresponda.\"]}]",
                "[\"Precio de visita guiada fijado y comunicado.\",\"Guion de visita segmentado por público.\",\"Repositorio audiovisual 4K y dron.\",\"Al menos un vínculo institucional o comercial nuevo iniciado.\"]"
