                'mariela',
                'cesia',
                "[\"Emprendimiento con más de 11 años de trayectoria ininterrumpida (desde 2013/2014) liderado por las hermanas María Eugenia y María José Gutiérrez, docentes de formación (Eugenia en nivel superior y Majo en artes visuales y preservación de patrimonio bibliográfico). Participaron oficialmente en dos ediciones de Puro Diseño en Buenos Aires.\",\"Propuesta identitaria de 'Diseño Mapuche Contemporáneo'. Como mujeres mapuche que participan activamente de la vida comunitaria y ceremonial (Camarruco), reinterpretan la memoria oral ancestral, la simbología cuatripartita (Choique), los puntos de telar (nimín) y leyendas de flora/fauna (Quñegüe) en piezas utilitarias modernas.\",\"Complementariedad técnica de excelencia: Majo domina ilustración manual/digital y encuadernación artística (costura en cuero/tela, mosaico en relieve, gofrado, hot stamping dorado/plateado y restauración). Euge domina marroquinería y serigrafía artesanal textil con matrices dobles sobre telas impermeables y repelentes al agua.\",\"Clientes corporativos y turísticos fieles de larga data: confeccionan desde hace 9 años las bitácoras de viaje y senderismo para una empresa de trekking en Tierra del Fuego; producen líneas para el Campo de Tulipanes y Casa Shagüe/Yagüe; libros de registro para Viñas de Nant y Fall y encuadernaciones para Cultura de Provincia.\",\"Canales actuales y dependencia de ferias: Históricamente comercializan en la feria artesanal municipal y por pedidos directos. Requieren formalizar un catálogo comercial B2B para que hoteles boutique, lodges de pesca y agencias de viaje incorporen su merchandising de manera recurrente.\"]",
                "[\"Dificultad para condensar el relato sin desvirtuar su valor: La cosmovisión mapuche y memoria oral de las piezas es profunda, pero en mostrador o feria el visitante muchas veces no dispone de tiempo para escucharla. Requieren un sistema de etiquetado de autor y marbetes con código QR que comuniquen el valor de la pieza en 30 segundos.\",\"Dispersión de talleres y asimetría de horarios docentes: Euge tiene disponibilidad por las mañanas y Majo por las tardes con horarios escolares rotativos. Cada una produce en su propio taller domiciliario (Barrio Chanico Navarro), lo que condiciona la producción en serie o la apertura permanente de taller al público.\",\"Inexistencia de catálogo comercial B2B para prestadores: Los prestadores turísticos (hoteles boutique, cabañas, agencias) no pueden visualizar cómo adaptar un estuche o bitácora a su establecimiento sin un muestrario claro de co-branding, escalas de precios por volumen y plazos de entrega.\",\"Dispersión de costos y necesidad de productos estandarizados de entrada: Piezas complejas de marroquinería ($40.000) o encuadernación pesada tienen rotación lenta. Se requiere consolidar una pirámide de productos con opciones de entrada ágiles (libretas de campo y bitácoras de viaje entre $8.000 y $15.000).\"]",
                "[{\"t\":\"Storytelling de Marca, Etiquetado y Colección 'Estampa Esquel'\",\"items\":[\"Sistema de marbetes colgantes y tarjetas de autenticidad de autor, con micro-relato identitario (nimín, Quñegüe, Choique) y código QR ampliado con fotos del proceso de serigrafía y encuadernación.\",\"Consolidación de la paleta cromática de temporada (colores tierra y verano patagónico) para la colección 'Estampa Esquel: Naturaleza Ancestral' en marroquinería y papelería.\",\"Estructuración de una pirámide de precios de 3 niveles: Acceso (libretas de mano y señaladores), Medio (bitácoras cosidas, cartucheras, tote bags impermeables) y Colección (cuadernos de cuero con grabado, mochilas de autor).\"]},{\"t\":\"Catálogo Comercial para Prestadores y Convenios de Canal\",\"items\":[\"Diseño de catálogo comercial digital interactivo (PDF interactivo y presentación web) orientado específicamente a hoteles boutique, agencias receptivas y organizadores de eventos.\",\"Muestrario de co-branding y personalización: mockups visuales de libretas y estuches que integran la estampa de autor con logotipos de establecimientos turísticos de Esquel.\",\"Fijación de lista de precios mayorista por escalas de volumen (pedidos de 20, 50 y 100 unidades) con plazos de entrega estandarizados (7 a 15 días) y facturación con monotributo.\"]},{\"t\":\"Prototipado de la Bitácora de Campo y Experiencia Piloto de Taller\",\"items\":[\"Desarrollo y testeo de la 'Bitácora de Campo y Registro de Montaña': libreta rústica de tapa blanda con cuadrícula de coordenadas (latitud/longitud), mapas de senderos, flora nativa y micro-poesías patagónicas.\",\"Prueba de campo de la bitácora con prestadores y guías de senderismo de la Célula 1 (Oficio) y Célula 4 (Canal).\",\"Proto-armado de un formato de 'Taller Abierto / Clínica de Estampado' para fechas especiales (temporada de tulipanes en octubre o verano) en grupos reducidos de 4 a 6 personas.\"]}]",
                "[\"Sistema de etiquetado narrativo y marbete con código QR listo para imprenta.\",\"Catálogo comercial B2B para hoteles, agencias y eventos turísticos con opciones de co-branding.\",\"Prototipo final de la 'Bitácora de Campo y Montaña' para senderismo y excursionismo.\",\"Matriz de costeo por volumen y capacidad de producción estandarizada para pedidos mayoristas.\",\"Muestrario de la Colección 'Estampa Esquel: Naturaleza Ancestral' en marroquinería y encuadernación.\",\"Al menos 3 convenios comerciales o acuerdos de provisión cerrados con alojamientos o receptivos.\"]"
            ],
            [
                'carpint',
                33,
                "Carpintero Esquel",
                "José Maximiliano Manquin",
                'Acelera',
                3.25,
                1,
                'mariela',
                'cesia',
                "[\"Artesano de la madera nacido y criado en Barrio Estación (Esquel, 38 años), con formación técnica formal de 3 años en carpintería de banco y torneado en el Centro de Formación Profesional (CFP) Nº 655 de calle Chacabuco, egresado con honores.\",\"Capacidad técnica y productiva demostrada en torno de madera y banco: confecciona cuencos, mates torneados, platos de asado, fuentes y mobiliario artesanal en maderas nobles (lenga, ciprés, radal). Dispone de taller de armado, torneado y lijado en el patio de su vivienda (calle Brown 1570) y utiliza la maquinaria pesada del Centro de Apoyo a la Producción de Esquel (CAPEC) pagando el canon de uso comunitario ('CAM') para tareas de cepillado y dimensionado grueso.\",\"Estructura familiar y vocación de arraigo: padre de 4 hijos (de 14, 10, 8 años y un lactante de 10 meses), su esposa es docente de nivel inicial y apoya en la gestión comercial. Disponibilidad horaria neta en turnos matutinos (08:30 a 14:30) y fines de semana para recepción turística.\"]",
                "[\"Cuello de botella en maquinado primario y estacionalidad edilicia: dependencia del taller del CAPEC para escuadrado y cepillado de tablones en bruto; taller hogareño expuesto al invierno cordillerano por falta de cerramiento y aislación térmica adecuada.\",\"Dispersión de catálogo y sub-costeo artesanal: coexistencia de pedidos a medida de carpintería general (muebles, aberturas) con piezas torneadas de souvenirs, sin una matriz que dimensione horas-hombre de torno, desgaste de gubias, lijas y acabados alimentarios no tóxicos (cera de abejas y aceite mineral).\",\"Falta de canales de comercialización fijos y experiencia vivencial inexplorada: inexistencia de puntos de venta en el circuito céntrico o tiendas de montaña, y desaprovechamiento del valor patrimonial del torno en vivo como experiencia turística comunitaria en Barrio Estación.\"]",
                "[{\"t\":\"Curaduría del Catálogo Turístico B2B (4 Piezas Estrella)\",\"items\":[\"Selección y estandarización de las 4 piezas insignia: Cuenco Mediano Torneado, Mate Rústico con Virola o Base Firme, Plato de Asado Patagónico y Cuchara Rústica con Grabado.\",\"Identidad y autenticidad: marca 'Carpintero Esquel' aplicada a fuego, etiqueta colgante de madera noble con origen regional y acabado no tóxico con aceites naturales.\"]},{\"t\":\"Experiencia 'Taller Abierto en Barrio Estación'\",\"items\":[\"Diseño de la vivencia turística para grupos reducidos (2 a 4 personas): demostración de torneado en vivo, participación en lijado y pulido de su propia pieza, marcado a fuego y mateada campesina tradicional.\",\"Protocolo estricto de bioseguridad: zona segura demarcada a 1,5 metros del torno, uso obligatorio de antiparras y protección auditiva; turista nunca opera herramientas de corte.\"]},{\"t\":\"Estructura de Costos, Canales Comerciales y Mejora de Infraestructura\",\"items\":[\"Planilla paramétrica de costos y fijación de precios mayoristas y minoristas para regionales y hoteles.\",\"Colocación en consignación en al menos 2 comercios céntricos con remito formal a 15 días.\",\"Articulación con Secretaría de Producción / CAPEC (Paula Botto) para formulación de proyecto de financiamiento para cerramiento y aislación del taller.\"]}]",
                "[\"Ficha técnica y costos estandarizados de las 4 piezas de la Línea Turística Estrella.\",\"Catálogo digital profesional (PDF y ficha técnica de producto) con fotografía 4K de piezas.\",\"Protocolo operativo y de seguridad para la experiencia 'Taller Abierto en Barrio Estación'.\",\"Acuerdo de consignación y colocación de stock inicial en al menos 2 comercios céntricos o regionales de Esquel.\",\"Proyecto técnico-económico de mejora edilicia del taller formulado para presentación ante líneas de crédito productivas.\"]"
            ],
            [
                'corcho',
                14,
                "Corcho Bikes",
                "Néstor Andrés Colinecul",
                'Acelera',
                3.13,
                4,
                'leandro',
                'agustina',
                "[\"Néstor Andrés 'Corcho' Colinecul pedalea desde los 11 años de forma continua (cumpliendo 50 años). Su padre le construyó su primera bicicleta en 1989, iniciando una carrera con múltiples títulos provinciales y regionales en ruta y MTB. Posee una autoridad técnica, deportiva y territorial inobjetable.\",\"Su taller mecánico en Barrio Los Sauces (calle 44, casa 28) opera desde 2019 a solo 2 cuadras de La Trochita y 3 de la subida al cementerio. Funciona espontáneamente como un club social barrial donde clientes y ciclistas pasan horas tomando mate mientras él realiza services mecánicos.\",\"Emprendimiento familiar con rol activo de su compañera y su hija (competidora y estudiante). Su compañera elabora dulces caseros tradicionales con fruta de la zona, aportando un elemento gastronómico de enorme calidez para complementar las paradas de las guiadas.\",\"Cuenta con posicionamiento orgánico en Google Maps con excelentes reseñas espontáneas de turistas de distintas provincias y de Brasil, quienes destacan su honestidad, rapidez y rescate mecánico inmediato.\",\"Presentó un proyecto social aprobado por la sede vecinal Los Sauces para enseñar mecánica básica, reciclaje de piezas y destreza a niños del barrio. El desafío es reorientar esa vocación comunitaria hacia un modelo de turismo activo rentable y sostenible.\"]",
                "[\"Carencia total de flota de bicicletas para excursionistas: Corcho solo cuenta con su propia bicicleta MTB de competición (habiendo vendido unidades previas). Se requiere resolver una flota puente de 6 a 8 unidades con cascos homologados.\",\"Protección del taller y delimitación horaria: El taller mecánico diario es el sustento de la familia. El cicloturismo debe circunscribirse estrictamente a martes, jueves y sábados por la tarde (a partir de las 14:30), preservando las mañanas para reparaciones.\",\"Reencuadre de guardería a turismo activo y seguros: Superar la idea original de 'guardería comunitaria' e inscribirse formalmente en el registro de Turismo Activo de Esquel, con póliza de seguro de accidentes personales para cicloturistas.\",\"Inexistencia de plataforma web institucional y material audiovisual profesional: Falta un sitio institucional que detalle los circuitos y permita reservas online. La conducción (Leandro) programará e implementará la plataforma web de forma gratuita.\",\"Fijación de costos y tarifario comercial: Superar la oferta ad-honorem o a la gorra, estructurando una matriz de costos que permita fijar tarifas rentables y ofrecer comisiones (15% a 20%) a agencias y recepciones de hoteles.\"]",
                "[{\"t\":\"Paquetización de Experiencias y Cápsula Familiar\",\"items\":[\"Circuito Familiar 'Pedaleo y Merienda en las Vías': dinámica de 2 hs donde los niños tienen una clínica lúdica de destreza y mecánica básica en un entorno seguro, mientras los padres descansan con mateada y degustación de dulces caseros frente a La Trochita.\",\"Circuito 'Esquel Lado B y Taller Abierto': para jóvenes y parejas, con un 'mini service participativo' de 15 min en el taller (calibración de frenos y cadena, mate con anécdotas de competencia) y pedaleo por senderos panorámicos del cementerio y Calle 10.\",\"Souvenir identitario sustentable: lapicero o portallaves de escritorio confeccionado en el taller con piezas recicladas (eslabones, piñones, rayos) y frasco de dulce casero artesanal con etiqueta 'Corcho Bikes · Esquel'.\"]},{\"t\":\"Gestión de Flota, Operatividad y Normativa\",\"items\":[\"Esquema de provisión de flota puente mediante convenio con bicicleterías locales o rodados municipales (6 bicis calibradas) y fondo de amortización para flota propia.\",\"Adquisición de kit de seguridad homologado: cascos para niños y adultos, chalecos reflectivos, conos de señalización y botiquín de primeros auxilios.\",\"Inscripción en Turismo Activo de Esquel, contratación de póliza de seguro de accidentes personales para excursionistas y fichas de deslinde de responsabilidad.\"]},{\"t\":\"Plataforma Web, Producción Audiovisual y Comercialización\",\"items\":[\"Benchmarking internacional de sitios web de bike-tours de autor (EE.UU., Europa) para definir layout y narrativa.\",\"Desarrollo y puesta en línea de la plataforma web oficial de Corcho Bikes por parte de Leandro (historia de Corcho, circuitos, galería y botón de reserva WhatsApp Business).\",\"Producción audiovisual oficial con equipo de la Subsecretaría: video 4K con dron sobre las vías de La Trochita y tomas cinematográficas de taller.\",\"Diseño e impresión de la ficha comercial de una carilla para mostradores de hoteles, cabañas y agencias de viaje con tarifario y comisiones cerradas.\"]}]",
                "[\"Guion técnico de los dos circuitos ('Familiar en las Vías' y 'Lado B Taller Abierto').\",\"Sitio web institucional de Corcho Bikes programado y puesto en línea (con motor de reservas WhatsApp).\",\"Banco audiovisual profesional (video 4K con dron en La Trochita + tomas de taller en alta resolución).\",\"Protocolo de flota operativa y kit de seguridad homologado (cascos y elementos de protección).\",\"Prototipo del souvenir identitario conector (lapicero de partes recicladas + dulce casero con packaging).\",\"Ficha comercial y tarifario cerrado con esquema de comisiones para el sector receptivo.\"]"
            ],
            [
                'retro',
                8,
                "Patagonia Retro",
                "Paula Salvo",
                'Acelera',
                3.12,
                1,
                'mariela',
                'cesia',
                "[\"Colección nostálgica de más de 7 años de objetos cotidianos e históricos de Esquel.\",\"Espacio físico en complejo de alojamiento.\",\"Gran potencial para museo vivencial y tienda vintage.\"]",
                "[\"Separación física del acceso para no invadir la privacidad de las cabañas.\",\"Guion museográfico y cédulas explicativas.\"]",
                "[{\"t\":\"Apertura al Público\",\"items\":[\"Diseño de recorrido y señalética independiente.\",\"Horarios fijos de visita para tardes de lluvia/descanso.\"]},{\"t\":\"Tienda Vintage\",\"items\":[\"Selección de antigüedades y réplicas a la venta.\",\"Entrada arancelada con consumición o recuerdo.\"]}]",
                "[\"Guion museográfico de las salas temáticas.\",\"Entrada y horarios fijados y comunicados a Turismo.\"]"
