            [
                'lucero',
                18,
                "Centro Integral Ecuestre Lucero",
                "María Soledad Arrechea",
                'Raíz',
                4.02,
                2,
                'adria',
                'noelia',
                "[\"Iniciativa de excelencia en turismo rural, de naturaleza y bienestar en predio cordillerano sobre Ruta 259 (km 25 / Barrio Los Cóndores), a mitad de camino entre Esquel y Trevelin. Cuenta con bosque centenario de pinos ('El Pinar'), matera histórica alemana, pista de monta y corrales en comodato con Carlos Baroli.\",\"Trayectoria consolidada y solvencia interdisciplinaria: titular bióloga y docente de biología (Colegio Salesiano y ex Escuela Experimental), cofundadora de la Fundación Patagónica de Equinoterapia (2011). Integra un equipo de salud (psicomotricista, kinesiólogo, psicóloga, docentes especiales y ecuestres) junto al programa comunitario 'Guardianes de Lucero'.\",\"Propuesta integral cuádruple: 1) Granja Educativa de Rescate (chinchillas, ratas de laboratorio, cerdita minipig Rita Uva, Pamperito de 35 años); 2) Escuela de Monta Consciente y Respetuosa (sin someter al caballo, pie a tierra y rienda suave); 3) Equinoterapia Interdisciplinaria con alta demanda sostenida; y 4) Terapias de Bienestar (yoga, meditación y constelaciones con caballos, coaching y feria El Paseo del Pinar).\"]",
                "[\"Dispersión de servicios y falta de paquetes turísticos estandarizados: necesidad de acotar la oferta para el visitante espontáneo a 2 experiencias claras con días y horarios fijos ('Granja Educativa' y 'Bautismo Ecuestre').\",\"Estacionalidad forrajera invernal: alto costo de alimentación de caballos (fardos de alfalfa y avena) en invierno por falta de pastura en el pinar, requiriendo un flujo turístico comercial que subsidie la sustentabilidad animal.\",\"Comercialización informal y falta de punto de venta: dependencia de consultas por redes sociales sin acuerdos con agencias receptivas de Esquel/Trevelin, y necesidad de un espacio rústico de venta física para el Kit infantil 'Pequeño Cuidador' y productos de granja en la matera histórica.\"]",
                "[{\"t\":\"Curaduría de 2 Experiencias Turísticas Estrella y Bioseguridad\",\"items\":[\"Experiencia 1: 'Granja Educativa & Saberes Vivos' (75 min, familiar y niños, historias de rescate, interacción guiada y merienda en la matera).\",\"Experiencia 2: 'Bautismo Ecuestre & Encuentro con el Caballo' (90 min, jóvenes y adultos, vínculo pie a tierra, monta consciente y paseo en El Pinar).\",\"Protocolo formal de bioseguridad ecuestre, deslindes de responsabilidad y seguros de turismo activo.\"]},{\"t\":\"Desarrollo del Kit 'Pequeño Cuidador' y Productos de Granja\",\"items\":[\"Lanzamiento del Kit 'Pequeño Cuidador / Guardián de Lucero' (libreta de campo ilustrada, lápiz ecológico, pin metálico de guardián y actividades).\",\"Línea de la granja: sobres de compost, semillas nativas y cuaderno editorial 'Historias de Lucero'. Acondicionamiento del puesto en la matera histórica.\"]},{\"t\":\"Estructura de Costos, Alianzas B2B y Ecosistema de Cohorte\",\"items\":[\"Planilla paramétrica de costos que amortice el forraje invernal y tarifario comercial B2C/B2B para agencias receptivas de Esquel y Trevelin.\",\"Catálogo digital interactivo, reservas por WhatsApp Business y sinergias con Haiku Casa de Té (retiros en El Pinar) y feria El Paseo del Pinar.\"]}]",
                "[\"Guion interpretativo y fichas técnicas estandarizadas de las 2 Experiencias Turísticas ('Granja Educativa' y 'Bautismo Ecuestre').\",\"Protocolo de bioseguridad ecuestre, formulario de deslinde de responsabilidad y manual de bienestar animal.\",\"Prototipo impreso del Kit 'Pequeño Cuidador de Animales / Guardián de Lucero' (libreta, pin y empaque).\",\"Planilla paramétrica de costos con amortización de forraje invernal y tarifario comercial minorista/mayorista (B2C/B2B).\",\"Convenio de comercialización turística con al menos 2 agencias receptivas habilitadas de Esquel/Trevelin y catálogo digital publicado.\"]"
            ],
            [
                'sabor',
                7,
                "Sabor Mapuche",
                "Lauriano Jose Rios",
                'Raíz',
                3.74,
                3,
                'adria',
                'francisco',
                "[\"Gastronomía ancestral de comunidades originarias, cocina de territorio y curanto.\",\"Gran potencia cultural, identidad e interés para turismo internacional y nacional.\",\"Cocineros y anfitriones reconocidos.\"]",
                "[\"Regularización bromatológica del espacio de elaboración.\",\"Continuidad de fechas regulares frente a la estacionalidad.\"]",
                "[{\"t\":\"Eventos Gastronómicos Fijos\",\"items\":[\"Establecer fechas de curanto y fuegos quincenales.\",\"Sistema de venta de cubiertos anticipados.\"]},{\"t\":\"Relato y Cultura\",\"items\":[\"Integrar la cosmovisión y el significado de los alimentos.\",\"Souvenir gastronómico (especias y conservas).\"]}]",
                "[\"Calendario de banquetes ancestrales con reserva.\",\"Ficha técnica para operadores de turismo receptivo.\"]"
            ],
            [
                'laberin',
                44,
                "El secreto del laberinto",
                "Marta Isabel San Martín",
                'Raíz',
                3.63,
                2,
                'adria',
                'noelia',
                "[\"Predio de 75 hectáreas (chacra familiar histórica, sucesión Austin) a 4 km de Esquel sobre Ruta 259, con frente de faldeo de monte y vistas panorámicas. Situación dominial resuelta y saneada. Parcela de casi 2 hectáreas asignada exclusivamente al laberinto vegetal.\",\"Equipo familiar con saberes complementarios: Marcelo Codesal (trabajo de campo y equinos), Florencia (Ingeniera Agrónoma que se recibe en diciembre 2026 y aporta rigor edáfico/botánico), Rocío (Lic. en Negocios Agropecuarios) y Joaquín (estudiante de Zootecnia y operador de cabalgatas). Marta posee amplia trayectoria en gastronomía (confitería concesionada) y terapias naturales.\",\"Infraestructura base avanzada: Perforación de agua nueva con bomba de alto caudal para riego por goteo, agua de vertiente para consumo, electricidad de red y platea de hormigón construida con acopio de materiales para salón de eventos/té de campo de 120 m² con sanitarios.\",\"Elección botánica perenne de 4 estaciones: Ligustro (Ligustrum) como especie estructurante para mantener el follaje verde en otoño e invierno bajo la nieve, complementado con especies florales nativas y arbustos decorativos en canteros centrales.\",\"Potencial de unidades puente inmediatas: En el predio habitan 14 a 15 caballos (6 propios mansos aptos para cabalgatas de faldeo), posibilitando activar paseos ecuestres, visitas al vivero de propagación y servicio de casa de té antes de la maduración definitiva del laberinto.\"]",
                "[\"Tiempos biológicos de crecimiento: El ligustro tarda de 3 a 5 temporadas en alcanzar altura adulta (1,80 a 2 m), aunque puede habilitarse prematuramente a 1 metro de altura con dinámicas lúdicas escolares y familiares. Se requiere estructurar actividades puente para generar ingresos inmediatos.\",\"Inversión económica inicial y necesidad de autoabastecimiento: Adquirir 4.000 plantas desarrolladas en viveros comerciales ($7.000 c/u) exigiría decenas de millones de pesos. Es imprescindible montar un vivero propio de multiplicación por esquejes con bioestimulación de sauce y riego asistido.\",\"Acondicionamiento del suelo árido y compactado: Para que los esquejes enraícen con vigor y ganen meses de crecimiento, se requiere un análisis agronómico de nutrientes/pH y una fuerte enmienda orgánica con abono de oveja (disponible en corrales familiares) y tierra negra antes de plantar.\",\"Trazado geométrico y replanteo de senderos: La traza circular concéntrica exige un Master Plan con mojones topográficos y asesoramiento paisajístico previo al zanjeo, además de rectificar la curva del camino de servidumbre que invadió parte de la parcela.\",\"Accesibilidad y validación comercial: Ubicado a 4 km del centro, debe validarse el perfil de transporte del visitante (auto particular vs taxi/receptivo), delimitar un estacionamiento para 30 vehículos y realizar encuestas de demanda (product-market fit) para afinar tarifas.\"]",
                "[{\"t\":\"Proyecto Agronómico, Suelo y Vivero de Multiplicación\",\"items\":[\"Muestreo y análisis de suelo en 4 sectores de la parcela para determinar pH, textura y nutrientes (conducido por Florencia Codesal), con enmienda masiva de abono de oveja y tierra negra.\",\"Diseño y montaje de un módulo rústico de vivero en el predio para propagar 4.000 esquejes de ligustro con enraizante natural de sauce y sistema de riego por goteo automatizado.\",\"Implantación de una parcela testigo con ligustros bajo condiciones óptimas para monitorear la tasa mensual de crecimiento y cerramiento perimetral con malla anti-liebres.\"]},{\"t\":\"Master Plan Paisajístico y Geometría del Laberinto\",\"items\":[\"Plano técnico del laberinto en formato circular concéntrico con senderos de 1,80 a 2,00 m de ancho, caminos ciegos, plazoleta central de descanso y mirador elevado.\",\"Asesoramiento paisajístico (Carolina de INTA) para fijar la densidad exacta de plantación por metro lineal y dimensionar la red de mangueras de goteo autocompensante.\",\"Zonificación del predio: sector laberinto, estacionamiento para 30 vehículos, salón de té/eventos, sendero de faldeo y corrales ecuestres.\"]},{\"t\":\"Prefactibilidad Económica, Fases de Apertura y Servicios Puente\",\"items\":[\"Matriz económica y presupuesto integral por etapas (Fase 1: cerco, vivero y salón de té; Fase 2: plantación y apertura a 1 m de altura; Fase 3: consolidación a 2 m todo el año).\",\"Estructuración de servicios puente inmediatos: casa de té de campo con repostería artesanal de Marta, cabalgatas guiadas de faldeo por Joaquín y visitas educativas al vivero.\",\"Encuesta de validación de demanda (product-market fit) para turistas en Esquel sobre movilidad, interés en atractivos rurales y disposición a pagar.\"]}]",
                "[\"Master Plan paisajístico y zonificación del predio (escala 1:500) con traza circular y replanteo de senderos.\",\"Informe agronómico de suelo y plan de enmienda orgánica con abono de oveja y tierra negra.\",\"Guía técnica y diseño del módulo de vivero para multiplicación de 4.000 esquejes de ligustro.\",\"Estudio de prefactibilidad económica y presupuesto por etapas a 3 años para búsqueda de financiamiento.\",\"Ficha técnica y operativa de los 'Servicios Puente' (casa de té de campo, cabalgatas y agroturismo).\",\"Informe de validación comercial y resultados de la encuesta de demanda turística en Esquel.\"]"
            ],
            [
                'nire',
                23,
                "Pausa de ñire",
                "Walter Cerdá",
                'Raíz',
                3.32,
                2,
                'adria',
                'noelia',
                "[\"Walter adquirió una fracción de 2 hectáreas de bosque de ñire hace 12 años tras desvincularse de un empleo formal de dos décadas. Construyó un cerco perimetral, abrió un camino de circunvalación interno y edificó una casita/salón cerrada con baño interno (biodigestor), estufa a leña, electricidad y agua.\",\"La propuesta no es trekking atlético ni aventura ni yoga. Se basa en el shinrin-yoku (técnica japonesa de inmersión en la naturaleza y conexión sensorial), enfocada en grupos reducidos (4 a 8 personas) que caminan despacio, se detienen, contemplan, escuchan y respiran el bosque cordillerano.\",\"Su esposa y colegas del CONICET identificaron una sorprendente variedad de microflora: líquenes raros en raíces y cortezas (con morfología de cornetitas o trúfulas), hongos patagónicos y flores nativas. Un recorrido de apenas 50 metros puede extenderse dos horas reloj con alto valor interpretativo y de macrofotografía.\",\"Walter cuenta con carnet profesional habilitante para transporte de personas, movilidad propia (camioneta apta para caminos de tierra) y experiencia como chofer trasladando visitantes a La Zeta. Además, dispone de 100% de dedicación horaria para el proyecto.\",\"Su hijo Imanol (13 años, con síndrome de Down) creció en el predio y desarrolló allí una notable independencia y seguridad. Esta vivencia real abre un diferencial conmovedor y escaso en la comarca: diseñar una experiencia de naturaleza y descanso accesible y sin miedos para familias con niños o personas con discapacidad.\"]",
                "[\"El predio está emplazado en Altos de Nant y Fall (jurisdicción de Trevelin). Si bien el programa adopta una visión comarcal de macrodestino, se hace imprescindible fijar una 'pata en Esquel' mediante experiencias en Laguna La Zeta para blindar el respaldo institucional ante sensibilidades políticas entre comunas.\",\"Desde la Ruta 17 hasta la tranquera del predio hay 1.500 metros de huella de campo que en invierno y deshielo se vuelve intransitable para autos convencionales sin tracción alta.\",\"El curso de guía con Forest Therapy Hub quedó demorado por cuestiones climáticas. Debe completarse la certificación vía remota mientras se avanza operativamente con lo que ya está en marcha, sin paralizar el negocio.\",\"Para el turista promedio, pagar por 'caminar entre los árboles' puede parecer poco tangible. La propuesta debe justificar su valor a través de un guion estructurado, dinámicas guiadas de silencio, ejercicios sensoriales y un cierre gastronómico/ceremonial con infusión nativa.\"]",
                "[{\"t\":\"Guion Sensorial y Turismo Inclusivo\",\"items\":[\"Estructurar un recorrido de 2 horas con momentos pautados: apertura y respiración, caminata en silencio ultra-lenta, observación de líquenes y microflora (lupa/macrofotografía), contemplación y cierre con infusión caliente de hojas de ñire.\",\"Formatear una cápsula para familias con integrantes con discapacidad, con actividades sencillas de conexión con el entorno, tiempos flexibles, apoyo a los padres y pautas de seguridad agreste.\",\"Creación de bolsitas de infusión de hojas de ñire con recolección sustentable, etiqueta artesanal con relato del árbol nativo y ficha de preparación para obsequiar o comercializar como recuerdo vivo.\"]},{\"t\":\"Estrategia de Macrodestino y Doble Nodo (La Zeta & Nant y Fall)\",\"items\":[\"Diseñar una variante periurbana en la Reserva Natural Urbana Laguna La Zeta (1h30m) para operar como opción de tarde inmediata en Esquel (días sin esquí o descanso entre excursiones largas).\",\"Operar la chacra como experiencia de medio día (3h a 4h) con traslado propio en camioneta desde el centro de Esquel o punto de encuentro sobre Ruta 17.\",\"Establecer un punto seguro de estacionamiento en la entrada del callejón para transbordar a los visitantes en la camioneta de Walter los días de lluvia o barro.\"]},{\"t\":\"Comercialización, Costeo y Alianzas\",\"items\":[\"Estructurar costos de combustible, seguro de accidentes personales, infusiones y honorarios del guía. Fijar tarifa individual y paquete cerrado para familias.\",\"Armado de la ficha técnica comercial en una carilla para recepcionistas de hoteles boutique de Esquel y agencias de turismo receptivo.\",\"Conexión con los prestadores de la Ruta 259 (Viñas de Nant y Fall, Chacra de Azafrán, Casas de Té) para recomendarse mutuamente en recorridos combinados de día completo.\"]}]",
                "[\"Guion técnico de la experiencia 'Pausa de Ñire' (Versión Chacra Nant y Fall y Versión periurbana Laguna La Zeta).\",\"Ficha comercial y tarifario cerrado para agencias y hoteles boutique.\",\"Prototipo de souvenir botánico empaquetado (bolsita de hojas de ñire con etiqueta y relato).\",\"Propuesta y protocolo de Turismo Accesible Familiar.\",\"Articulación comercial iniciada con al menos 2 alojamientos de Esquel o prestadores de la Ruta 259.\"]"
            ],
            [
                'truepat',
                13,
                "TRUE PATAGONIA",
                "Cecilia Fernanda Simonini",
                'Raíz',
                3.25,
                4,
                'mariela',
                'noelia',
                "[\"Cecilia Fernanda Simonini (radicada en Esquel hace 10 años por elección pura) combina un perfil técnico, artístico y naturalista excepcional: técnica en electrónica, diseñadora gráfica, formación en pastelería, naturalista egresada de Aves Argentinas (trabajo de campo y educación ambiental) y tejedora en telar mapuche, crochet, peine e hilandera en huso tradicional en el Centro Cultural Melipal.\",\"Amplia experiencia en el sector turístico receptivo de Esquel: trayectoria en Las Bayas (hotelería boutique), Frontera Sur (agencia receptiva, rental, esquí y concesiones en Parque Nacional Los Alerces como Cabañas El Chaltén, Camping Lago Verde y Restaurante El Aura), y piezas textiles para Maipú. Reside en el periurbano (detrás de Chacra Los Álamos), en conexión directa con la vida de campo.\",\"Propuesta de valor transformadora y vivencial: 'hacer y experimentar en lugar de solo observar'. Ciclo completo de la lana (oveja, esquila, hilado en huso, recolección botánica de tintes naturales y telar mapuche), alfarería rústica, cosmovisión con nociones de mapuzungun y cocina al rescoldo/horno de barro, complementado con cápsulas de crochet en el paisaje cordillerano.\"]",
                "[\"Disonancia del nombre provisorio anglosajón ('True Patagonia') frente a una propuesta de raíz ancestral mapuche-tehuelche y criolla profunda, señalada unánimemente por el jurado.\",\"Cuello de botella en la base de alojamiento: pretender concentrar todo en una sola chacra rural con ovejas frena el proyecto por falta de infraestructura hotelera adecuada (calefacción, camas de confort, baños privados) en parajes comarcales.\",\"Sobrecarga operativa al estar sola: necesidad de estructurar el encuadre legal, seguros de turismo activo/asistencia al viajero y comercialización mediante convenios con agencias de viajes receptivas (EVyT) habilitadas.\"]",
                "[{\"t\":\"Deconstrucción de Marca y Reposicionamiento de Autor\",\"items\":[\"Reemplazo de 'True Patagonia' por una denominación de autor con anclaje comarcal y calidez patagónica.\",\"Construcción de la persona pública de Cecilia como activo irreplicable, anfitriona y puente de confianza con el campo.\"]},{\"t\":\"Modelo 'Punta de Lanza' y Curaduría Emocional\",\"items\":[\"Base de alojamiento en cabañas periurbanas o predios seleccionados (Establecimiento Las Margaritas de Lorena Cogos en Nahuelpan) e incursiones diarias a chacras de Alto Río Percy y parajes.\",\"Diseño del itinerario de 4 días / 3 noches con curva dramática: momentos de calma, silencios, mateadas campesinas y picos de asombro artesanal.\"]},{\"t\":\"Souvenir Físico Conector y Comercialización Receptiva\",\"items\":[\"Diseño y prototipado editorial de la 'Bitácora Textil y Carpeta de Saberes' (fichas botánicas, fórmulas de tinte, glosario mapuzungun y muestras de lana hilada/teñida).\",\"Estructuración de costos B2B/B2C, punto de equilibrio (4 pasajeros), encuadre de turismo activo y convenio marco con agencia receptiva (EVyT) para venta anticipada.\"]}]",
                "[\"Manual de Marca y Relato de Autor desarticulando el nombre foráneo.\",\"Itinerario Técnico Guionado (4 Días / 3 Noches) y Cápsula Full Day 'Patrones de Montaña & Crochet'.\",\"Prototipo Editorial Impreso de la 'Bitácora Textil y Carpeta de Saberes' con packaging de bienvenida.\",\"Convenio preliminar de uso de espacio con Establecimiento Las Margaritas y predios campesinos de Percy.\",\"Ficha Comercial B2B, matriz de costeo integral con margen de agencia y modelo de seguro de turismo activo.\"]"
